create table site_widgets(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,channel_id int not null references channels,public_key text not null unique,name text not null,origins text[] not null,title text not null default 'Como podemos ajudar?',greeting text not null default 'Olá! Envie sua mensagem.',color text not null default '#6254e8',active boolean not null default true,created_at timestamptz not null default now());
create table site_sessions(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,widget_id int not null references site_widgets,contact_id int not null references contacts,token_hash text not null unique,expires_at timestamptz not null default now()+interval '30 days',created_at timestamptz not null default now());
create table comm_settings(tenant_id int primary key default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,value jsonb not null default '{}');
create table credit_sources(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,name text not null,provider text not null check(provider in ('openrouter','manual','managed')),secret text,currency text not null default 'USD',threshold numeric not null default 5,balance numeric,checked_at timestamptz,status text not null default 'unknown',error text,alarm_open boolean not null default false,active boolean not null default true);
create table comm_alerts(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,source_id int references credit_sources,title text not null,body text not null,created_at timestamptz not null default now(),resolved_at timestamptz);
create table comm_deliveries(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,alert_id bigint references comm_alerts,channel text not null,target text not null,subject text not null,body text not null,status text not null default 'pending',external_id text,error text,created_at timestamptz not null default now(),sent_at timestamptz,unique(alert_id,channel,target));
do $$declare r record;begin for r in select * from(values('site_widgets','channels,channel_id'),('site_sessions','site_widgets,widget_id,contacts,contact_id'),('comm_settings',''),('credit_sources',''),('comm_alerts','credit_sources,source_id'),('comm_deliveries','comm_alerts,alert_id')) v(t,refs) loop execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',r.t);if r.refs<>'' then execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.refs,',')) x));end if;end loop;end $$;
create function resolve_site_widget(k text) returns int language sql security definer set search_path=public as $$select w.tenant_id from site_widgets w join tenants t on t.id=w.tenant_id join channels c on c.id=w.channel_id where w.public_key=k and w.active and t.active and c.active limit 1$$;
revoke all on function resolve_site_widget(text) from public;
do $$ begin if exists(select 1 from pg_roles where rolname='vexora_app') then grant execute on function resolve_site_widget(text) to vexora_app;end if;end $$;
create index site_session_widget on site_sessions(tenant_id,widget_id);
create index comm_pending on comm_deliveries(tenant_id,status,created_at);
alter table comm_deliveries add column request_key text;
create unique index comm_request_once on comm_deliveries(tenant_id,request_key) where request_key is not null;
alter table credit_sources add column fingerprint text,add column auto_managed boolean not null default false;
create unique index credit_fingerprint on credit_sources(tenant_id,provider,fingerprint) where fingerprint is not null;
alter table comm_deliveries add column actor_id int default nullif(current_setting('app.actor',true),'')::int references users;
create trigger comm_actor_guard before insert or update on comm_deliveries for each row execute function fk_guard('users','actor_id');
